// 단계별 문제 — 중3 영어(eng-g3.js 8차시) · 고1 공통영어(eng-h1.js 8차시) · 고2 영어Ⅰ·Ⅱ(eng-h2.js 8차시). 2022 개정 교육과정 기준. 지문·대화문·예문은 모두 자작.
window.DATA = window.DATA || {}; (window.DATA.problemsAdd = window.DATA.problemsAdd || []).push({

 /* ======================= 중3 1학기 · 가정법과 분사구문 ======================= */
 "eng-g3-cond-sub": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nIf I ___ about the test earlier, I would have studied harder.", opts:["knew","had known","have known","know"], a:1, exp:"주절이 would have studied(가정법 과거완료) → if 절은 **had p.p.** → had known. knew 는 가정법 과거(주절 would + 동사원형)와 짝이다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화의 빈칸에 알맞은 것은?\n\nA: You look so tired today.\nB: I stayed up late playing games. I wish I ___ to bed earlier.", opts:["go","went","had gone","have gone"], a:2, exp:"'어젯밤에 일찍 잤더라면' — 이미 지난 과거 사실의 반대 → **I wish + had p.p.** went 는 '지금 일찍 자면 좋을 텐데'라는 현재 사실 반대라 문맥에 맞지 않는다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Last winter, my cousin Jiho visited a small village in the mountains. He acted **(A) as if he knew** every path, but he got lost before lunch. If he **(B) had brought** a map, he would not have wasted three hours. Now he says, \"I wish I **(C) had been** more careful then.\" If I were him, I **(D) will carry** a map next time. Still, he loved the quiet village and wants to go back.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"If I were him(가정법 과거)의 주절은 **would + 동사원형** → would carry. (A) as if + 과거형, (B) had p.p. + would have p.p., (C) 과거 후회의 I wish + had p.p.는 모두 바르다.", why3:"1등급 포인트 — if 절이 were/과거형이면 주절에 will 은 절대 불가. 주절 조동사를 먼저 보고 if 절 시제와 짝을 맞춘다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 쓰시오.\n① As it is raining, we can't go hiking. → If 로 시작하는 가정법 문장으로\n② '내가 네 번호를 알았더라면, 너에게 전화했을 텐데.' (know, call 활용) 영작", model:"① If it were not raining, we could go hiking.\n② If I had known your number, I would have called you.", rubric:[["① were not raining / could go",3],["① 긍정·부정 뒤집기(is raining → were not)",2],["② had known + would have called",3],["철자·어순",2]], exp:"①은 현재 사실의 반대 → 가정법 과거(were/could). 부정을 뒤집지 않으면 뜻이 반대가 된다. ②는 과거 사실의 반대 → 가정법 과거완료.", err:"개념" }
 ],

 "eng-g3-cond-part": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nThe children were ___ by the ___ magic show.", opts:["amazed – amazing","amazing – amazed","amazed – amazed","amazing – amazing"], a:0, exp:"아이들은 놀라움을 **느끼는** 쪽 → amazed, 마술 쇼는 놀라움을 **일으키는** 쪽 → amazing. 주어가 사람이면 p.p., 사물이면 -ing 가 대부분이다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?", opts:["Not knowing what to say, he just smiled.","The boy wearing a red cap is my brother.","Being cold outside, we stayed at home.","I found a letter written in French."], a:2, exp:"날씨의 주어 it 과 주절 주어 we 가 다르므로 주어를 남겨야 한다 → **It being** cold outside. ① Not + -ing, ② 능동 수식 -ing, ④ 수동 수식 p.p.는 바르다.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Walking home from school, I saw an old man **(A) sitting** alone on a bench. He looked **(B) tired** and was holding a **(C) breaking** bag full of oranges. **(D) Not wanting** to pass by, I stopped and helped him pick them up. He thanked me with a warm smile, and the surprising thing was that he was my new neighbor. Since then, we have had tea together every Sunday afternoon.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:2, exp:"가방은 '찢어진(당한)' 쪽이므로 과거분사 **broken** bag. (A) 노인이 '앉아 있는' 능동 → sitting, (B) look + 형용사, (D) 분사구문 부정은 Not + -ing 로 모두 바르다.", why3:"1등급 포인트 — 명사 앞 분사는 '그 명사가 하는가(-ing) 당하는가(p.p.)' 한 번만 물으면 끝. bag 은 찢는 주체가 아니다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 쓰시오.\n① Because I was tired after the game, I went to bed early. → 분사구문으로\n② '그 영화는 지루했고, 우리는 지루했다.' (bore 활용) 영작하고, 두 분사의 형태가 다른 이유를 쓰시오.", model:"① (Being) Tired after the game, I went to bed early.\n② The movie was boring, and we were bored.\n이유: 영화는 지루함을 일으키는 쪽이므로 현재분사 boring, 우리는 지루함을 느끼는 쪽이므로 과거분사 bored 를 쓴다.", rubric:[["① 접속사·주어 제거 + (Being) Tired",3],["② boring / bored 정확",3],["일으킴 -ing · 느낌 p.p. 이유",2],["시제·철자",2]], exp:"①에서 Being 은 생략 가능. ②를 The movie was bored 로 쓰면 '영화가 지루함을 느꼈다'는 뜻이 되어 0점.", err:"개념" }
 ],

 /* ======================= 중3 1학기 · 관계사 심화와 완료 시제 ======================= */
 "eng-g3-relperf-adv": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nDo you know the reason ___ the shop closed early today?", opts:["which","where","why","what"], a:2, exp:"선행사 the reason(이유) + 뒤 문장 the shop closed early 가 완전 → 관계부사 **why**(= for which). which 는 뒤가 불완전할 때, what 은 선행사가 없을 때 쓴다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?", opts:["I don't believe what he told me.","She bought a car, which was very expensive.","This is the city which I was born.","I remember the day when we first met."], a:2, exp:"I was born 은 완전한 문장이므로 관계대명사 which 불가 → **where**(= in which) I was born. ① 선행사 없는 what, ② 계속적 용법 which, ④ 관계부사 when 은 바르다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"My grandmother lives in a small town **(A) where** the trains stop only twice a day. Last summer I stayed with her, **(B) that** was the best part of my vacation. **(C) What** I loved most was the morning market. Every day she bought fresh bread, **(D) which** she shared with her neighbors. I want to visit again this winter and learn how she bakes her famous apple pie.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:1, exp:"콤마 뒤 계속적 용법에는 that 을 쓸 수 없다 → **which**(앞 문장 전체를 받음). (A) 뒤가 완전 → where, (C) 선행사 없음 → what, (D) 콤마 + which(목적격)는 바르다.", why3:"1등급 포인트 — 콤마가 보이면 that 과 what 부터 지운다. 계속적 which 는 앞 문장 전체를 받을 수 있다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 쓰시오.\n① This is the park. + We played soccer there. → 관계부사를 써서 한 문장으로\n② '나는 네가 말한 것을 이해하지 못했다.' (understand, say 활용) 영작하고, 관계대명사 what 을 쓰는 이유를 쓰시오.", model:"① This is the park where we played soccer.\n② I didn't understand what you said.\n이유: 앞에 선행사(명사)가 없고 '~한 것'이라는 명사 덩어리를 만들어야 하므로 the thing which 를 뜻하는 what 을 쓴다.", rubric:[["① where + 완전한 절",3],["② what you said",3],["선행사 없음 이유 서술",2],["시제 일치(didn't / said)·철자",2]], exp:"①에서 there 를 남기면(where we played soccer there) 감점. ②를 that you said 로 쓰면 선행사가 없어 0점.", err:"개념" }
 ],

 "eng-g3-relperf-perfect": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nWhen I called her, she ___ already ___ for the airport.", opts:["has – left","had – left","was – left","have – left"], a:1, exp:"기준 시점 called(과거)보다 '떠남'이 먼저 → **과거완료 had left**. already 가 단서. 현재완료는 기준이 '지금'일 때만 쓴다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화의 빈칸에 알맞은 것은?\n\nA: You look exhausted. What have you been doing?\nB: I ___ my room since six this morning, and it's still not done.", opts:["am cleaning","have been cleaning","had cleaned","cleaned"], a:1, exp:"since + 시작 시점 + '아직 끝나지 않음(still not done)' → 과거부터 지금까지 진행 중인 **현재완료진행** have been cleaning. had cleaned 는 기준 과거 시점이 없어 불가.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Before Mina moved to Busan last year, she **(A) had never seen** the sea. She has **(B) been living** near the beach since then, and she still walks there every morning. Last week, by the time I arrived at her house, she **(C) had already left** for the beach. She says she has **(D) been knowing** every rock on the shore. I think the sea has changed her life.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"know 는 상태동사라 진행형 불가 → has **known**. (A) moved(과거)보다 먼저 → had never seen, (B) since then + 지금도 거주 → 현재완료진행, (C) by the time + 과거 → had left 는 바르다.", why3:"1등급 포인트 — been + -ing 가 보이면 동사가 상태동사(know/like/belong)인지 먼저 확인. 나머지 완료 시제는 '기준 시점'으로 판단.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"괄호 안 동사를 알맞은 형태로 쓰고, 각각 그 형태를 쓰는 이유를 쓰시오.\n① By the time the bell rang, the students (finish) the test.\n② It (rain) for three hours, and it is still raining.", model:"① had finished — 종이 울린 과거 시점(rang)보다 시험을 끝낸 일이 먼저 일어났으므로 과거완료(had p.p.)를 쓴다.\n② has been raining — 세 시간 전에 시작해 지금도 계속 내리는 중(still raining)이므로 현재완료진행(have been -ing)을 쓴다.", rubric:[["① had finished",2],["① 먼저 일어난 일(대과거) 이유",3],["② has been raining",2],["② 지금도 진행 중 이유",3]], exp:"①을 finished 로 쓰면 두 일의 순서가 드러나지 않아 감점. ②를 has rained 로 쓰면 '지금도 내리는 중'이 약해져 감점.", err:"개념" }
 ],

 /* ======================= 중3 2학기 · 접속사·수동태 심화 ======================= */
 "eng-g3-conjpass-conj": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nI'll lend you my notes ___ you return them by Friday.", opts:["unless","as long as","so that","even though"], a:1, exp:"'금요일까지 돌려주는 **한**' 빌려주겠다 → 조건 **as long as**. unless 는 '돌려주지 않으면'이라 뜻이 반대, so that 뒤에는 can/will 이 필요하다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?", opts:["Not only the teacher but also the students were surprised.","She whispered so that nobody could hear her.","Unless it will rain, we will go hiking.","Even though he was sick, he came to school."], a:2, exp:"조건 접속사 unless 뒤에는 미래 대신 **현재시제** → Unless it **rains**. ① B(the students)에 수일치, ② so that + could, ④ even though 는 바르다.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Our school started a \"quiet hour\" in the library last month. Students can use the room ______ they keep their phones in their bags. At first, many students complained. Some even said they would not come unless the rule was changed. However, after two weeks, most of them said they could focus much better. Now the library is full every afternoon, and teachers are planning a second quiet room.", q:"윗글의 빈칸에 들어갈 말로 가장 알맞은 것은?", opts:["unless","as long as","even though","so that"], a:1, exp:"'휴대전화를 가방에 넣어 두는 **한**(조건) 이용할 수 있다' → as long as. unless 는 '넣지 않으면', even though 는 양보, so that 은 뒤에 can/will 이 와야 한다.", why3:"1등급 포인트 — 접속사 빈칸은 앞뒤를 '~하는 한/~않으면/~지만/~하려고' 중 하나로 번역한 뒤 고른다. 뒤 문장에 can/will 이 없으면 so that 은 소거.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 바꿔 쓰시오.\n① I study hard in order to pass the exam. → so that 을 써서\n② If you don't wear a coat, you'll catch a cold. → unless 를 써서 쓰고, not 이 사라지는 이유를 쓰시오.", model:"① I study hard so that I can pass the exam.\n② Unless you wear a coat, you'll catch a cold.\n이유: unless 는 if ~ not(…하지 않으면)의 뜻을 이미 담고 있어서 not 을 또 쓰면 이중 부정이 되어 뜻이 뒤집힌다.", rubric:[["① so that + I can pass",3],["② Unless you wear",3],["이중 부정 이유 서술",2],["조건절 현재시제·철자",2]], exp:"①에서 so that I pass(조동사 없음)는 감점. ②를 Unless you don't wear 로 쓰면 해당 항목 0점.", err:"개념" }
 ],

 "eng-g3-conjpass-passive": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nA nice dinner was cooked ___ us by my aunt.", opts:["to","for","of","by"], a:1, exp:"cook·make·buy 는 직접목적어가 주어인 수동태에서 간접목적어 앞에 **for** 를 쓴다. give·send·show·tell 은 to.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **옳은** 것은?", opts:["He was made clean the classroom.","The baby was named Hana by her parents.","This book must read by everyone.","The cat was taken care by my sister."], a:1, exp:"5형식 수동태는 보어(Hana)를 제자리에 둔다 → 바르다. ① 사역동사 수동태는 to clean, ③ 조동사 + be p.p. → must be read, ④ 구동사는 한 덩어리 → taken care **of** by.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Last Friday, our class **(A) was given** a special task by the principal. We **(B) were asked** to make the school garden beautiful before the festival. Some students were made **(C) pull** out weeds, and others painted the fence. The old bench was **(D) looked after** by Jiho, who fixed its broken leg. By Sunday, the garden was full of flowers, and the principal called it the best in town.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:2, exp:"사역동사 make 의 수동태에서는 동사원형이 **to부정사**로 바뀐다 → were made **to pull**. (A) 4형식 수동태(간접목적어 주어), (B) ask + O + to V 의 수동태, (D) 구동사 수동태는 바르다.", why3:"1등급 포인트 — be made/seen/heard 뒤에 동사원형이 보이면 즉시 의심. 능동의 '원형 보어'는 수동에서 to 가 부활한다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 쓰시오.\n① My uncle sent me a postcard. → 가능한 수동태 문장 두 가지\n② We saw him enter the room. → 수동태로 쓰고, to 가 나타나는 이유를 쓰시오.", model:"① I was sent a postcard by my uncle. / A postcard was sent to me by my uncle.\n② He was seen to enter the room (by us).\n이유: 지각동사 뒤의 동사원형 보어는 수동태가 되면 to부정사로 바뀐다.", rubric:[["① 간접목적어 주어형(I was sent ~)",2],["① 직접목적어 주어형 + to me",3],["② was seen to enter",3],["to 부활 이유 서술",2]], exp:"①에서 A postcard was sent me(전치사 누락)는 감점. ②를 was seen enter 로 쓰면 해당 항목 0점. entering 도 인정하는 학교가 있으나 원형은 불가.", err:"개념" }
 ],

 /* ======================= 중3 2학기 · 강조·도치·간접화법과 독해·영작 ======================= */
 "eng-g3-emphread-emph": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 부분을 It ~ that 강조 구문으로 강조할 수 **없는** 것은?", opts:["**My sister** baked this cake.","I met Tom **at the library**.","She **lost** her wallet yesterday.","We watched **a movie** last night."], a:2, exp:"It ~ that 은 주어·목적어·부사구를 강조하며 **동사는 강조할 수 없다**. 동사를 강조하려면 do/does/did + 동사원형(She did lose her wallet).", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화의 빈칸에 알맞은 것은?\n\nA: I didn't like the ending of the movie.\nB: ___ It was too sad.", opts:["So did I.","Neither did I.","Neither I did.","So I didn't."], a:1, exp:"앞 말이 **부정문**이므로 '나도 그렇지 않았다'는 **Neither + 조동사 + 주어** → Neither did I. So 는 긍정문에 동의할 때, Neither I did 는 도치가 안 된 어순이다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"When I was ten, my grandfather told me that he **(A) had once built** a boat. \"Never **(B) have I seen** such a strong boat,\" my mother said. It was my grandfather **(C) that** taught me how to tie a rope. Last summer he asked me **(D) that** I wanted to sail with him. Of course I said yes, and we spent a whole week on the lake. I do hope we can sail together again.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"의문문(Do you want to sail with me?)의 간접화법은 **asked + if/whether + 주어 + 동사** → asked me **if** I wanted. (A) told 보다 먼저 → 과거완료, (B) 부정어 도치, (C) 주어 강조 It ~ that 은 바르다.", why3:"1등급 포인트 — asked 뒤의 접속사는 if/whether 또는 의문사. that 은 평서문 전달(told/said)에만 쓴다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 바꿔 쓰시오.\n① Tom said to me, \"I can't come to your party tonight.\" → 간접화법으로\n② I had never tasted such sweet grapes. → Never 로 시작하는 문장으로", model:"① Tom told me (that) he couldn't come to my party that night.\n② Never had I tasted such sweet grapes.", rubric:[["① told me + couldn't",3],["① your → my, tonight → that night 전환",2],["② Never had I tasted 어순",3],["철자·구두점",2]], exp:"①은 전달동사(told)·시제(couldn't)·대명사(my)·시간 부사(that night) 네 가지를 모두 채점. ②에서 Never I had tasted 는 도치 항목 0점.", err:"개념" }
 ],

 "eng-g3-emphread-read": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"글의 흐름과 **무관한** 문장은?\n\nKeeping a diary in English helps you learn. ① You practice writing every day. ② You learn new words naturally. ③ English dictionaries are sold in many stores. ④ You can also see how much you have improved.", opts:["①","②","③","④"], a:2, exp:"핵심어는 '영어 일기 쓰기의 이점'. ③은 English 라는 단어만 겹칠 뿐 '사전 판매'로 방향이 다르다. ①②④는 모두 일기 쓰기의 이점을 말한다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"조건을 모두 지킨 영작은?\n\n(조건: 11단어, so that 과 could 사용 / '나는 그 기차를 탈 수 있도록 일찍 일어났다.')", opts:["I got up early so that I could catch the train.","I got up early in order to catch the train.","I got up early so that I catch the train.","I got up early so that could I catch the train."], a:0, exp:"①만 11단어·so that·could·평서문 어순을 모두 만족. ②는 so that 없음, ③은 could 없음, ④는 so that 뒤 어순(주어 + 조동사) 오류.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"[주어진 글] Last month, our class decided to clean the stream behind the school.\n(A) After three hours, we had collected twelve bags of trash, and the water looked clear again.\n(B) These bags were mostly full of plastic bottles and snack wrappers from the road above. Now a sign by the road asks drivers to keep their trash.\n(C) On Saturday morning, twenty of us met at the bridge with gloves and bags.", q:"주어진 글 다음에 이어질 글의 순서로 가장 적절한 것은?", opts:["(A)-(C)-(B)","(C)-(A)-(B)","(C)-(B)-(A)","(B)-(A)-(C)"], a:1, exp:"결정(주어진 글) → 토요일에 모임(C) → 세 시간 뒤 쓰레기 열두 봉지(A) → **These bags** 가 (A)의 twelve bags 를 받음(B). (B)의 대명사가 (A) 없이는 가리킬 대상이 없다.", why3:"1등급 포인트 — These/This + 명사는 '앞에 그 명사가 이미 나왔다'는 신호. 대명사 사슬이 끊기는 순서는 바로 소거.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건을 모두 지켜 영작하시오.\n(조건: ① 가정법 과거완료 사용 ② 12단어 ③ miss, bus 를 변형 없이 사용)\n'내가 더 일찍 떠났더라면, 나는 그 버스를 놓치지 않았을 텐데.'", model:"If I had left earlier, I would not have missed the bus.\n(점검: had left ↔ would not have missed 시제 짝, 12단어, miss·bus 그대로 사용)", rubric:[["had left (if 절 과거완료)",3],["would not have missed",3],["12단어·miss·bus 조건 충족",2],["철자·구두점",2]], exp:"wouldn't 로 줄이면 11단어가 되어 단어 수 조건 위반. If I left earlier(가정법 과거)는 '과거 사실의 반대'가 아니므로 if 절 항목 0점.", err:"실수" }
 ],

 /* ======================= 고1 공통영어1 · 어법 ======================= */
 "eng-h1-gram-verb": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nThe number of students who join the club ___ every year.", opts:["increase","increases","are increasing","have increased"], a:1, exp:"주어의 핵심은 **The number**(단수). students who join the club 은 수식어이므로 괄호로 묶는다 → increases. a number of 였다면 복수 동사.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?", opts:["The accident happened while I was cooking.","Each of the rooms has its own key.","Most of the money were spent on books.","If it rains tomorrow, the game will be canceled."], a:2, exp:"most of + 명사는 그 명사에 일치 → money(셀 수 없음, 단수) → **was** spent. ① happen 은 자동사(수동 불가), ② each → 단수, ④ 조건 부사절은 현재시제가 바르다.", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"The paintings in the old hall **(A) were made** by a local artist a century ago. Since then, thousands of visitors **(B) have walked** past them without noticing the tiny birds in each corner. Last year, a student who loved the paintings **(C) discovered** the birds and wrote a report. Now a small sign explaining the secret **(D) are placed** under each painting, and visitors stop to count them.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"주어는 **a small sign**(단수)이고 explaining the secret 은 수식어 → **is placed**. (A) 목적어 없음 + by → 수동, (B) since then → 현재완료, (C) last year → 과거는 바르다.", why3:"1등급 포인트 — 동사 바로 앞 명사(secret)가 아니라 수식어를 벗긴 '진짜 주어'에 수를 맞춘다. 분사구·관계절·전치사구는 괄호로.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"괄호 안 동사를 알맞은 형태로 쓰고, 각각 그 이유를 쓰시오.\n① The letters (write) by soldiers during the war (be) kept in the museum.\n② Half of the apples in the basket (be) rotten.", model:"① written, are — 본동사 자리(be)가 따로 있으므로 write 는 준동사이고, 편지는 '쓰인' 쪽이므로 과거분사 written. 주어는 The letters(복수)이므로 are.\n② are — half of + 복수 명사(apples) → 복수 동사.", rubric:[["① written (수동 분사)",3],["① are (복수 주어 letters)",3],["② are (half of + 복수 명사)",2],["이유 서술(진짜 주어·수동 관계)",2]], exp:"①에서 wrote 를 쓰면 한 문장에 동사가 둘이 되어 0점. ②에서 basket 에 맞춰 is 를 쓰면 of 뒤 명사 일치 원칙 위반.", err:"개념" }
 ],

 "eng-h1-gram-nonfinite": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 알맞은 것은?\n\nI forgot ___ the window, so the room was freezing when I came back.", opts:["close","closing","to close","closed"], a:2, exp:"'창문을 닫아야 할 일을 잊었다'(그래서 추웠다) → **forget + to-v**(앞으로 할 일). forget + v-ing 는 '닫은 사실을 잊다'로 문맥과 맞지 않는다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?", opts:["Despite the rain, the match went on.","I don't know what she wants for her birthday.","The hotel where we stayed had a great view.","He gave up to smoke last year."], a:3, exp:"give up 은 **동명사** 목적어 → gave up **smoking**. ① despite + 명사구, ② 선행사 없는 what, ③ 뒤가 완전한 절(we stayed) → 관계부사 where 는 바르다.", err:"개념" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Many people believe **(A) that** talent decides success. However, researchers who studied young musicians found something else. The students **(B) who** practiced the most, not the most gifted ones, became the best players. **(C) Seen** this way, daily effort matters more than raw talent. So instead of asking **(D) that** makes a person special, ask how many hours they have spent on their craft.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"asking 뒤에 선행사가 없고 makes 의 주어가 빠진 불완전한 절 → **what** makes. (A) believe + 완전한 절 → 접속사 that, (B) 주격 who, (C) '보여지는' 수동 분사구문 Seen 은 바르다.", why3:"1등급 포인트 — 전치사(of) 뒤·선행사 없음·불완전한 절 세 가지가 겹치면 what. 접속사 that 은 완전한 절 앞에만.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 바꿔 쓰시오.\n① This is the house in which my grandmother was born. → 관계부사를 써서\n② Because he was raised in Jeju, he swims very well. → 분사구문으로 쓰고, 과거분사로 시작하는 이유를 쓰시오.", model:"① This is the house where my grandmother was born.\n② (Being) Raised in Jeju, he swims very well.\n이유: 주절 주어 he 는 '길러진' 쪽(수동)이므로 Being raised 가 되고, Being 을 생략하면 과거분사 Raised 로 시작한다.", rubric:[["① where",3],["② Raised in Jeju (Being 생략 가능)",3],["수동 → p.p. 이유 서술",2],["철자·구두점",2]], exp:"①에서 which 만 쓰면(the house which my grandmother was born) 전치사가 빠져 0점. ②를 Raising in Jeju 로 쓰면 능동이 되어 해당 항목 0점.", err:"개념" }
 ],

 /* ======================= 고1 공통영어1 · 독해 유형 입문 ======================= */
 "eng-h1-read-main": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 글의 요지로 가장 적절한 것은?\n\nMany people think a good leader must talk the most in every meeting. But the best leaders in our study spent more time listening. They asked short questions and let others finish their ideas.", opts:["리더는 발표 능력을 먼저 길러야 한다.","좋은 리더는 말하기보다 듣기에 시간을 쓴다.","질문이 많은 팀은 결정이 느리다.","리더십은 타고나는 것이다."], a:1, exp:"첫 문장은 통념, **But** 뒤 문장이 주제문(listening). ①은 통념 쪽, ③④는 지문에 근거가 없다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 들어갈 말로 가장 적절한 것은?\n\nOur brains treat a half-finished task like an open door. We keep thinking about it until it is closed. That is why writing a to-do list helps: it tells the brain the task ___.", opts:["is impossible","will be handled","was never important","needs more time"], a:1, exp:"'열린 문'(미완 과제)은 '닫혀야' 생각이 멈춘다 → 목록에 적으면 뇌에 '처리될 것'이라고 알려 준다. ①③④는 '문을 닫는' 역할과 어긋난다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Most people clean their desks when they feel stressed, but a messy desk is not always a problem. In one study, workers at untidy desks produced more creative ideas than those at tidy ones. The clutter seemed to free their minds from fixed patterns. Of course, a desk buried under old papers can slow you down. The point is not to keep everything perfect but to know when a little mess helps.", q:"윗글의 제목으로 가장 적절한 것은?", opts:["Clean Desk, Clear Mind","A Little Mess Can Help You Think","How to Organize Old Papers","Why Workers Feel Stressed"], a:1, exp:"마지막 문장 'to know when a little mess helps' 가 요지 → 약간의 어수선함이 사고를 돕는다. ①은 통념(반대), ③은 지문에 없는 방법, ④는 첫 문장 소재만 다룬 좁은 제목.", why3:"1등급 포인트 — 제목은 마지막 문장(not A but B)의 B 를 압축. 첫 문장 단어(clean, stressed)로 만든 보기는 통념 함정.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 글의 요지를 영어 한 문장(8~12단어)으로 쓰고, 근거가 된 문장을 하나 골라 그 문장이 주제문인 이유(연결어·명령문 등)를 쓰시오.\n\nMany students highlight whole pages while reading. However, marking everything is the same as marking nothing. Choose only the one sentence that answers the question of the paragraph.", model:"요지: Highlight only the key sentence instead of marking everything.\n근거: 'However, marking everything is the same as marking nothing.' — 역접 However 뒤에서 통념(전부 표시)을 뒤집고, 마지막 명령문(Choose only ~)이 같은 내용을 재진술하므로 주제문이다.", rubric:[["요지 문장: '핵심만 표시' 포함",4],["8~12단어의 완전한 문장",2],["근거 문장 선택",2],["However/명령문 이유 서술",2]], exp:"첫 문장(Many students highlight ~)을 요지로 쓰면 통념이라 0점. 요지는 우리말이 아닌 영어 문장으로.", err:"추론" }
 ],

 "eng-h1-read-detail": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"안내문의 내용과 일치하지 **않는** 것은?\n\nGreen Hill Photo Contest\n· Theme: Our Town in Autumn\n· Deadline: October 20\n· Entry: free for students, $3 for adults\n· Up to 2 photos per person\n· Winners announced on the school website on November 1", opts:["주제는 가을의 우리 마을이다.","학생은 무료로 참가할 수 있다.","1인당 사진 3장까지 낼 수 있다.","수상자는 학교 누리집에 발표된다."], a:2, exp:"Up to 2 photos per person → 1인당 **2장**까지. 나머지는 안내문과 일치한다. 숫자 하나만 바꾼 보기가 단골 오답.", err:"자료" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 **him** 이 가리키는 것은?\n\nMina showed her brother the photo she had taken of their dog. He laughed because the dog looked just like **him** when he wakes up in the morning.", opts:["Mina","her brother","their dog","the photo"], a:1, exp:"'개가 아침에 일어났을 때의 **그**와 꼭 닮았다' — 비교 대상은 개가 아닌 사람, 웃은 주체인 her brother. the dog 을 넣으면 '개가 개와 닮았다'가 되어 어색하다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"| 통학 방법(%) | 2018 | 2024 |\n| 도보 | 40 | 30 |\n| 자전거 | 10 | 25 |\n| 버스 | 35 | 30 |\n| 자가용 | 15 | 15 |\n\nThe table shows how students went to school each day in 2018 and 2024. ① Walking was the most common way in 2018. ② The share of students who cycled more than doubled over the period. ③ Bus use fell by five percentage points. ④ In 2024, more students cycled than took the bus to school. It hopes its new bike lanes will draw even more riders next year.", q:"표의 내용과 일치하지 **않는** 문장은?", opts:["①","②","③","④"], a:3, exp:"2024년 자전거 25% < 버스 30% → ④가 틀렸다. ① 2018년 도보 40%가 최다, ② 10 → 25 는 두 배 이상, ③ 35 → 30 은 5%p 감소로 모두 맞다.", why3:"1등급 포인트 — 도표 문장은 '비교 표현 + 숫자'를 하나씩 대조. more than doubled 는 '2배 초과', percentage points 는 비율의 차이.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", q:"표에서 자전거 통학 비율은 2018년 10%에서 2024년 25%로 변했다.\n① 이 변화를 percentage points 를 써서 영어 한 문장으로 쓰시오.\n② 'increased by 15 percent' 라고 쓰면 틀린 이유를 쓰시오.", model:"① The share of students who cycled to school increased by 15 percentage points from 2018 to 2024.\n② 비율(%) 사이의 차이는 percentage point 로 나타낸다. 10%에서 25%는 2.5배(150% 증가)이므로 '15 percent 증가'는 수치가 틀린 표현이다.", rubric:[["increased by 15 percentage points",4],["주어·기간이 있는 완전한 문장",2],["percent 와 percentage point 구별 설명",3],["철자·수치",1]], exp:"①에서 15 percent 또는 15% 라고 쓰면 핵심 항목 0점. ②는 '차이는 %p, 배율·증가율은 %'라는 구별이 드러나야 만점.", err:"자료" }
 ],

 /* ======================= 고1 공통영어2 · 글의 구조 ======================= */
 "eng-h1-str-order": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"주어진 문장이 들어가기에 가장 적절한 곳은?\n\n[문장] But the real reason was simpler.\n\nOur team lost the final last week. (①) Some said the field was too wet. (②) Others blamed the referee. (③) We had not practiced together for a month. (④)", opts:["①","②","③","④"], a:2, exp:"But 은 앞의 핑계들(wet field, referee)과 반대되는 '진짜 이유'를 예고 → 그 이유(연습 부족) 바로 앞인 ③. ①②는 아직 다른 이유들이 다 나오기 전이다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"주어진 글 다음에 이어질 순서로 가장 적절한 것은?\n\nJisu found an old key in her grandmother's drawer.\n(A) Inside was a letter written to her grandmother fifty years ago.\n(B) It opened a small wooden box under the bed.\n(C) She asked her grandmother what it was for, but she only smiled.", opts:["(A)-(B)-(C)","(B)-(A)-(C)","(C)-(B)-(A)","(C)-(A)-(B)"], a:2, exp:"열쇠 발견 → 용도를 물음(C) → It(= the key)이 상자를 엶(B) → Inside(= the box 안)에 편지(A). (A)의 Inside 는 (B)의 box 가 먼저 나와야 가리킬 수 있다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"[주어진 글] In 1900, a small bakery in our town began giving away its leftover bread every evening.\n(A) Because of this tradition, the bakery is still loved today, and its line stretches around the corner every Friday.\n(B) At first, only a few poor families came for the free bread.\n(C) Word spread quickly, however, and soon dozens of people were waiting outside by sunset.", q:"주어진 글 다음에 이어질 글의 순서로 가장 적절한 것은?", opts:["(A)-(C)-(B)","(B)-(A)-(C)","(B)-(C)-(A)","(C)-(B)-(A)"], a:2, exp:"**At first**(B) → **however**, 소문이 퍼져 수십 명(C) → **this tradition** 으로 현재까지 이어짐(A). (A)의 today 는 결론 신호이므로 맨 뒤.", why3:"1등급 포인트 — At first → however → today 의 시간·전환 사슬. 결론(today/still)이 있는 단락을 앞에 두는 선택지부터 소거.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"순서를 배열하고, 단락 첫머리의 형태 단서(대명사·연결어·지시어) 두 가지 이상을 들어 근거를 쓰시오.\n\n[주어진 글] Mina planted a tomato seed in a paper cup.\n(A) Thanks to this care, a tiny leaf finally appeared.\n(B) But she kept watering it every morning and moved it to the window.\n(C) Nothing happened for a week, and she almost gave up.", model:"순서: (C)-(B)-(A)\n근거: (C)의 Nothing happened 는 씨를 심은 직후의 상황이고, (B)의 But 은 '포기할 뻔했다'와 반대되는 전환이며 it 은 the seed 를 받는다. (A)의 this care 는 (B)의 물 주기·옮기기를 가리키므로 (B) 뒤에 온다.", rubric:[["순서 (C)-(B)-(A)",4],["단서 ① But(역접) 설명",2],["단서 ② this care(지시어) 설명",2],["대명사 it 등 추가 단서의 정확성",2]], exp:"순서만 맞고 근거가 '내용상 자연스럽다'뿐이면 단서 항목 0점. 형태 단서(But, this care, it)를 이름 붙여 써야 득점.", err:"추론" }
 ],

 "eng-h1-str-summary": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"전체 흐름과 관계 **없는** 문장은?\n\nDrinking water before meals can help you eat less. ① A glass of water fills part of the stomach. ② So people feel full sooner. ③ Bottled water is sold in many flavors these days. ④ In one study, water drinkers ate 75 fewer calories per meal.", opts:["①","②","③","④"], a:2, exp:"주제어는 '식전 물 → 덜 먹음'. ③은 water 라는 단어만 쓰고 '생수 판매'로 주제를 벗어난다. ③을 빼고 읽으면 ② → ④가 자연스럽게 이어진다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"요약문의 빈칸에 알맞은 것은?\n\nIn an experiment, people who wrote down their worries for ten minutes before a test scored higher than those who sat quietly.\n→ Writing about worries before a test ___ performance.", opts:["lowers","improves","delays","ignores"], a:1, exp:"결과 scored higher → 성적이 **향상**(improves). lowers 는 반대 방향, delays·ignores 는 지문에 근거가 없다.", err:"어휘" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Researchers asked two groups of students to learn a word list. One group studied the list four times. The other studied it once and then tested themselves three times from memory. A week later, the self-testing group remembered almost twice as many words. Rereading felt easier, but it left weaker memories. They concluded that the effort of recalling is what makes learning last.", q:"다음 글의 내용을 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것은?\n\n→ Although (A) feels easier, (B) leads to longer-lasting memory.", opts:["(A) testing – (B) rereading","(A) rereading – (B) self-testing","(A) rereading – (B) repetition","(A) recalling – (B) comfort"], a:1, exp:"'rereading felt easier' → (A) rereading, '자기 시험 집단이 두 배 기억' → (B) self-testing. ①은 두 칸이 뒤바뀜, ③은 repetition 이 rereading 과 같은 쪽, ④는 comfort 가 결과가 아니다.", why3:"1등급 포인트 — 요약문의 Although 는 '기분(쉬움)'과 '결과(기억)'의 대조. (A)만 맞고 (B)가 같은 편인 보기(③)를 조심.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 글을 '주어 + 동사'를 갖춘 영어 한 문장(10~15단어)으로 요약하고, 요약에 쓴 핵심어 두 개가 지문의 어떤 표현을 바꿔 쓴 것인지 쓰시오.\n\nPeople who take short walks during the workday report fewer afternoon headaches. Even five minutes away from the screen helps the eyes and the mind rest.", model:"요약: Taking short walks during work reduces headaches by letting the eyes and mind rest.\n바꿔 쓰기: reduces ← fewer (headaches), letting ~ rest ← helps the eyes and the mind rest(또는 away from the screen).", rubric:[["요약문: 걷기 → 두통 감소의 인과 포함",4],["10~15단어의 완전한 문장",2],["바꿔 쓴 핵심어 2개 제시",3],["철자·문법",1]], exp:"지문 문장을 그대로 베끼면 요약이 아니므로 바꿔 쓰기 항목 0점. 원인(걷기)과 결과(두통 감소)가 둘 다 있어야 만점.", err:"추론" }
 ],

 /* ======================= 고1 공통영어2 · 어휘·서술형 ======================= */
 "eng-h1-vocab-context": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"문맥상 낱말의 쓰임이 적절하지 **않은** 것은?\n\nOur town built a new bike path last year. Since then, the number of cyclists has ①risen, and the air near the road has become ②cleaner. However, some shop owners say sales have ③increased because fewer people park cars downtown. The city plans to ④add more bike racks.", opts:["①","②","③","④"], a:2, exp:"However + '불평(say)' + '주차하는 사람이 줄어서' → 매출은 **dropped(감소)**. increased 로 바꿔 읽으면 불평하는 이유가 사라진다. ①②④는 자전거 도로의 긍정 효과와 방향이 맞다.", err:"어휘" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"(A), (B), (C)에 알맞은 낱말의 짝은?\n\nThe new rule will (A) [affect / effect] everyone. Please (B) [lie / lay] the books on the desk, and keep (C) [quiet / quite] during the test.", opts:["affect – lay – quiet","effect – lie – quiet","affect – lie – quite","effect – lay – quite"], a:0, exp:"(A) 동사 자리 → affect(effect 는 명사). (B) 목적어 the books 가 있음 → 타동사 lay(lie 는 자동사). (C) keep + 형용사 → quiet(quite 는 부사 '꽤').", err:"어휘" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Many people assume the best way to improve at chess is to play as many games as possible. Yet top players spend more time **(A) studying** old games than playing new ones. By reviewing each move slowly, they **(B) notice** patterns that a fast game hides. Beginners who only play tend to **(C) avoid** the same mistakes. Careful review, not endless play, is what turns **(D) weakness** into skill.", q:"윗글의 밑줄 친 (A)~(D) 중 문맥상 낱말의 쓰임이 적절하지 **않은** 것은?", opts:["(A)","(B)","(C)","(D)"], a:2, exp:"글의 방향: 복기(review)가 실력을 만들고, '놀기만' 하면 실력이 늘지 않는다 → 초보자는 같은 실수를 **repeat(반복)**한다. avoid 는 반대 방향. (A)(B)(D)는 주장과 같은 방향이다.", why3:"1등급 포인트 — Yet 뒤에서 글의 방향(복기 > 많이 두기)을 고정한 뒤, 밑줄을 반의어로 바꿔 읽어 더 자연스러운 곳이 정답.", err:"어휘" },
  { lv:3, kind:"essay", tag:"서술형", q:"① 영영 풀이에 맞는 단어를 주어진 첫 글자로 시작하여 쓰시오.\n'to change something so that it fits a new situation' → a______\n② 다음 문장을 명사 effect 를 써서 같은 뜻의 문장으로 바꿔 쓰시오.\nThe cold weather affected the crops.", model:"① adapt\n② The cold weather had an effect on the crops.", rubric:[["① adapt (adopt 는 0점)",3],["② had an effect on",4],["② 과거시제 had · 관사 an",2],["철자",1]], exp:"adapt(적응시키다·맞추다)와 adopt(채택하다·입양하다)는 철자 혼동어. ②에서 effected 처럼 동사로 쓰면 0점 — effect 는 명사이므로 have an effect on 으로.", err:"어휘" }
 ],

 "eng-h1-writing-serial": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"우리말에 맞게 바르게 배열한 것은?\n\n'그가 나에게 준 조언은 매우 유용했다.' (the advice / gave / was / he / me / very useful)", opts:["The advice he gave me was very useful.","The advice was very useful he gave me.","He gave me the advice was very useful.","The advice gave he me was very useful."], a:0, exp:"뼈대 The advice was very useful + 명사 바로 뒤에 관계절(which 생략) he gave me. ②는 관계절이 명사에서 떨어졌고, ③④는 동사가 둘이거나 어순이 깨졌다.", err:"실수" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"조건을 모두 지킨 영작은?\n\n(조건: 가주어 It 사용, 11단어 / '매일 영어로 일기를 쓰는 것은 중요하다.')", opts:["It is important to write a diary in English every day.","To write a diary in English every day is important.","It is important writing a diary in English every day.","It is important to write a diary in English."], a:0, exp:"①만 It ~ to부정사 + 11단어. ②는 가주어 없음, ③은 to부정사가 아닌 -ing, ④는 every day 가 빠져 9단어(뜻과 단어 수 모두 위반).", err:"실수" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Keeping a journal in a second language **(A) is** one of the cheapest ways to improve. You do not need a teacher, and you can write **(B) whenever** you like. At first, your sentences will be short and full of mistakes, but that is **(C) exactly** how learning works. After a few months, you will read your first pages and **(D) surprised** at how far you have come.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"will **read** ~ and **be surprised** — and 앞뒤를 동사원형으로 병렬해야 하므로 be 가 필요하다. (A) 동명사 주어 → 단수 is, (B) whenever + 절, (C) 부사 exactly 가 how 절 수식은 바르다.", why3:"1등급 포인트 — and 뒤에 p.p.나 -ing 가 홀로 있으면 and 앞으로 돌아가 '무엇과 병렬인가'를 확인. 서술형 어형 변화에서도 똑같이 채점된다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건을 모두 지켜 영작하시오.\n(조건: ① 관계대명사 사용 ② 과거완료 사용 ③ 11~14단어 ④ lose, wallet, buy 활용)\n'내가 어제 잃어버린 지갑은 내 삼촌이 사 주셨던 것이었다.'", model:"The wallet which I lost yesterday was the one my uncle had bought.\n(= The wallet that I lost yesterday was what my uncle had bought for me.)", rubric:[["관계대명사 which/that + I lost",3],["had bought (과거완료)",3],["단어 수·주어진 단어 조건 충족",2],["주어-동사 수일치(The wallet ~ was)·철자",2]], exp:"잃어버린 것(어제, 과거)보다 산 것이 먼저이므로 had bought. 관계절 뒤의 동사를 were 로 쓰거나 bought 로만 쓰면 각 항목 감점.", err:"실수" }
 ],

 /* ======================= 고2 영어Ⅰ·Ⅱ · 수능 듣기 ======================= */
 "eng-h2-listen-purpose": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 안내 방송의 목적으로 가장 적절한 것은?\n\nAttention, shoppers. Thank you for visiting Green Mall today. Please note that the east parking lot is closed for repairs this week, so please use the north entrance when you leave. We apologize for the inconvenience.", opts:["연장 영업 시간을 홍보하려고","주차장 폐쇄와 대체 출입구를 안내하려고","할인 행사 상품을 소개하려고","주차 요금 변경을 알리려고"], a:1, exp:"Please note ~ closed ~ so please use the north entrance 가 요청 = 목적. Thank you 는 인사이고, 영업 시간·할인·요금은 언급되지 않았다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화를 읽고, 두 사람의 관계로 가장 적절한 것은?\n\nW: Could you move a little to the left? The light is hitting your glasses.\nM: Like this?\nW: Perfect. Now hold the diploma and smile.\nM: Can I see the shot after this one?\nW: Of course. I'll show you on the screen.", opts:["안경사 – 손님","사진사 – 손님","교사 – 학생","미용사 – 손님"], a:1, exp:"light, hold the diploma and smile, the shot, show you on the screen → 사진을 찍는 사람과 찍히는 사람. glasses 는 안경사 함정 어휘.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"M: Mom, the science fair is tomorrow and I still have a lot to do.\nW: Let's split the work. I already printed the posters last night.\nM: Thanks. Then I'll finish the model volcano now.\nW: Good. What about the handouts?\nM: Could you copy them at the office?\nW: Sure, I'll do that after lunch.\nM: And I'll borrow a table from Mr. Park.\nW: Then everything will be ready by tonight.", q:"대화를 읽고, 여자가 할 일로 가장 적절한 것은?", opts:["포스터 인쇄하기","화산 모형 완성하기","유인물 복사하기","탁자 빌리기"], a:2, exp:"Could you copy them? → Sure, I'll do that 가 여자의 합의된 일. 포스터는 **이미(already)** 인쇄했고, 화산 모형과 탁자는 남자(I'll ~)가 맡는다.", why3:"1등급 포인트 — '누가 할 일'인지 먼저 표시. already 가 붙은 일은 이미 끝난 일이고, 상대방의 I'll ~ 은 오답 보기로 나온다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 대화의 빈칸을 조건에 맞게 영작하고, 이 대화에서 남자가 할 일을 영어 한 문장으로 쓰시오.\n(조건: Could you ~? 사용, 8~10단어, drive 활용 / '내일 아침에 저를 공항까지 태워다 주실 수 있나요?')\n\nW: Dad, my flight leaves at 9 tomorrow. ______?\nM: Sure. I'll wake you up at six.", model:"빈칸: Could you drive me to the airport tomorrow morning?\n남자가 할 일: The man will drive the woman to the airport (and wake her up at six).", rubric:[["Could you drive me to the airport",4],["tomorrow morning + 단어 수·물음표",2],["남자가 할 일 영어 문장(will drive / wake her up)",3],["철자·대소문자",1]], exp:"Could you take me ~ 는 drive 조건 위반으로 감점. 남자가 할 일은 Sure 뒤의 합의(태워다 주기)이며 '일찍 깨우기'는 부가 정보.", err:"실수" }
 ],

 "eng-h2-listen-detail": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화를 읽고, 남자가 지불할 금액을 고르시오.\n\nM: How much are these mugs?\nW: $6 each, but if you buy four, you get one more for free.\nM: Then I'll take four. Do you have gift boxes?\nW: Yes, $1 each.\nM: I'll take two boxes, please.", opts:["$24","$26","$30","$32"], a:1, exp:"머그 4개 × $6 = $24(다섯 번째는 무료라 추가 비용 없음) + 상자 2개 × $1 = $2 → **$26**. 무료 머그를 $6 으로 더하면 $30 함정.", err:"계산" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"대화를 읽고, 남자가 영화를 보러 갈 수 **없는** 이유를 고르시오.\n\nW: Are you coming to the movie tonight?\nM: I'd love to, but I can't.\nW: Is it because of your part-time job?\nM: No, I quit that last week. My little brother has a piano recital, and I promised to be there.", opts:["아르바이트가 있어서","동생의 피아노 발표회에 가야 해서","영화표를 구하지 못해서","몸이 아파서"], a:1, exp:"'I'd love to, but' 뒤의 진짜 이유는 동생의 발표회. 아르바이트는 No 로 부정되었고(지난주에 그만둠), 표·건강은 언급이 없다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Good afternoon, everyone. I'm happy to introduce our Winter Reading Challenge. It begins on December 1 and runs for six weeks. Students in all grades can take part, and there is no fee. To join, pick up a reading card at the library desk and record each book you finish. Anyone who reads eight or more books will receive a certificate and a bookstore coupon. For details, visit the school website.", q:"Winter Reading Challenge 에 관해 언급되지 **않은** 것은?", opts:["시작일","참가 대상","참가비","시상식 장소"], a:3, exp:"시작일(December 1), 참가 대상(all grades), 참가비(no fee), 참여 방법, 상품은 나오지만 **시상식 장소**는 언급이 없다. '참가비 없음'도 참가비가 '언급된' 것이다.", why3:"1등급 포인트 — 선택지 순서대로 ✓를 찍으며 듣는다. 'no fee'처럼 부정으로 언급된 항목을 '언급 안 됨'으로 착각하지 말 것.", err:"자료" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 대화를 읽고 ① 남자가 지불할 총액을 계산 과정과 함께 쓰고, ② 마지막 남자의 말에 이어질 여자의 응답을 영어 한 문장으로 쓰시오.\n\nM: I'd like three T-shirts. How much are they?\nW: They're $12 each, and today everything is 25% off.\nM: Great. I'll also take this cap for $8.\nW: The discount applies to the cap, too.\nM: Then I'll pay by card.", model:"① 티셔츠 $12 × 3 = $36, 모자 $8 → 소계 $44. 25% 할인 → $44 × 0.75 = **$33**.\n② Sure. Please insert your card here. (= OK, here is the card reader.)", rubric:[["소계 $44 계산",3],["할인 적용 최종 $33",3],["응답 문장이 카드 결제 상황에 자연스러움",3],["철자·문법",1]], exp:"할인을 티셔츠에만 적용해 $27 + $8 = $35 로 쓰면 최종 금액 항목 0점(여자가 모자도 할인된다고 말함). 응답은 마지막 말(결제 방법)에 맞아야 한다.", err:"계산" }
 ],

 /* ======================= 고2 영어Ⅰ·Ⅱ · 독해 대의 파악 ======================= */
 "eng-h2-read-purpose": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 글의 목적으로 가장 적절한 것은?\n\nDear Mr. Choi,\nThank you for letting our club use the music room this semester. Unfortunately, the piano has two broken keys, which makes practice difficult. I would appreciate it if you could arrange a repair before our concert on May 20.\nSincerely, Yuna Kim", opts:["피아노 수리를 요청하려고","음악실 사용 허가에 감사하려고","연주회 참석을 요청하려고","음악실 사용 시간을 연장하려고"], a:0, exp:"'I would appreciate it if you could arrange a repair' 가 목적 문장. Thank you 는 인사, 연주회는 수리 기한을 말하는 배경이다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 글에 드러난 'I'의 심경 변화로 가장 적절한 것은?\n\nThe gym was silent as I stepped onto the balance beam. My legs felt like jelly, and I could hear my own heartbeat. Then the music began, and my body remembered every move. When I landed the final jump, the crowd roared and I laughed out loud.", opts:["nervous → joyful","bored → excited","confident → ashamed","calm → worried"], a:0, exp:"legs like jelly, heartbeat(긴장) → Then 이후 body remembered, laughed out loud(기쁨). ③④는 순서가 반대, ②는 처음 감정이 지루함이 아니다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Most people believe multitasking saves time. In reality, the brain cannot focus on two hard tasks at once; it simply switches between them, and every switch costs attention. Students who text while studying take longer and remember less. If you want to finish faster, close the other windows and give one task your full attention. Doing one thing at a time is not slower. It is the shortcut.", q:"윗글에서 필자가 주장하는 바로 가장 적절한 것은?", opts:["공부할 때는 휴대전화를 멀리 두어야 한다.","한 번에 한 가지 일에 집중해야 한다.","어려운 과제는 둘로 나누어 처리해야 한다.","집중력은 꾸준한 훈련으로 길러진다."], a:1, exp:"명령문 'give one task your full attention' + 결론 'Doing one thing at a time ~ is the shortcut' 이 주장. ①은 예시(texting) 하나만 다룬 좁은 보기, ③④는 지문에 없다.", why3:"1등급 포인트 — 주장은 명령문·should 문장과 마지막 재진술을 겹쳐 확인. 예시 속 단어(text, windows)로 만든 보기는 범위가 좁다.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"조건에 맞게 요청 이메일의 핵심 문장을 영작하고, 이 문장이 들어간 글의 목적을 우리말로 쓰시오.\n(조건: ① 'I am writing to' 로 시작 ② ask if 사용 ③ 12~15단어 ④ extend, deadline 활용)\n'저는 귀하께서 기한을 다음 주 금요일까지 연장해 주실 수 있는지 여쭈어 보려고 씁니다.'", model:"I am writing to ask if you could extend the deadline until next Friday.\n목적: 마감 기한 연장을 요청하려고.", rubric:[["I am writing to ask if",3],["you could extend the deadline until next Friday",4],["단어 수·조건 충족",1],["목적을 우리말로 정확히 서술",2]], exp:"ask if 뒤는 평서문 어순(you could). 'ask that you extend' 는 조건 위반. 목적을 '감사하려고'처럼 인사와 혼동하면 0점.", err:"실수" }
 ],

 "eng-h2-read-topic": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"다음 글의 제목으로 가장 적절한 것은?\n\nOctopuses can change color in less than a second. Special cells in their skin open and close like tiny curtains. This lets them hide from sharks or warn rivals without moving an inch.", opts:["How Sharks Hunt in the Dark","The Octopus: A Master of Quick Disguise","Why Sea Animals Move Slowly","Colors of the Deep Ocean"], a:1, exp:"핵심어 change color(빠르게) + hide/warn(위장·신호) → 빠른 변장의 달인. ①은 예시 속 sharks 만, ③은 반대, ④는 너무 넓다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"안내문의 내용과 일치하는 것은?\n\nSpring Photo Walk\n· Sunday, April 12, 9 a.m. – noon\n· Meet at the north gate of River Park\n· Fee: $5 (includes a snack)\n· Bring your own camera or phone\n· Limited to 20 people; register by e-mail by April 8", opts:["토요일 오전에 진행된다.","참가비에 간식이 포함된다.","카메라를 빌려준다.","당일 현장 등록이 가능하다."], a:1, exp:"Fee: $5 (includes a snack) → 일치. 일요일(Sunday), 카메라는 직접 지참(Bring your own), 4월 8일까지 이메일 사전 등록이므로 나머지는 불일치.", err:"자료" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"For centuries, sailors used stars to cross open water. Today, satellites do the job, but some navies still teach star navigation to young officers. The reason is simple: electronic systems can fail or be jammed, while the sky cannot be switched off. Learning the old method also trains officers to watch the sea instead of a screen. Old skills, it turns out, are a kind of insurance.", q:"윗글의 주제로 가장 적절한 것은?", opts:["why satellites replaced star navigation","the value of old skills as a backup for modern technology","how sailors memorize the positions of stars","dangers of relying on young officers at sea"], a:1, exp:"핵심어 old method/skills + insurance(대비책) 둘 다 든 ②. ①은 첫 두 문장 배경만, ③은 지문에 없는 방법, ④는 young officers 단어만 빌린 함정.", why3:"1등급 포인트 — 주제는 반복 핵심어 두 개(old skills, insurance/backup)를 모두 담은 명사구. 핵심어 하나만 든 보기는 소거.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 표를 보고 ① 과학 동아리와 미술 동아리의 비율을 배수 표현(twice as ~ as)으로 비교하는 영어 문장, ② 가장 인기 없는 동아리를 최상급으로 나타내는 영어 문장을 쓰시오.\n\n[표] 1학년 희망 동아리(%): 음악 40 · 체육 24 · 과학 24 · 미술 12", model:"① The science club was twice as popular as the art club.\n② The art club was the least popular of the four (clubs).", rubric:[["① twice as popular as",3],["① 비교 대상(science / art) 정확",2],["② the least popular",3],["시제·철자",2]], exp:"①에서 twice more popular than 은 감점. ②에서 the most unpopular 도 인정하나 of the four 처럼 범위를 쓰면 더 정확하다.", err:"자료" }
 ],

 /* ======================= 고2 영어Ⅰ·Ⅱ · 추론: 빈칸·함축·어휘·어법 ======================= */
 "eng-h2-infer-blank": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"빈칸에 들어갈 말로 가장 적절한 것은?\n\nA beginner cook follows the recipe line by line. An expert reads it once and then adjusts the heat, the salt, and the timing. The difference is not knowledge of ingredients but ___.", opts:["the price of the dishes","the freedom to depart from the rules","the number of recipes memorized","the speed of chopping"], a:1, exp:"초보는 레시피를 '그대로', 전문가는 '조정(adjusts)' → 차이는 **규칙에서 벗어날 자유**. ①④는 근거 없음, ③은 '지식'과 같은 편이라 not A but B 의 B 가 될 수 없다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 **a gym, not a theater** 가 의미하는 바로 가장 적절한 것은?\n\nSome teachers answer every question at once. Ms. Park waits. She lets the silence sit until a student tries an answer. Her classroom, she says, is **a gym, not a theater**.", opts:["학생이 직접 시도하며 힘을 기르는 곳이다.","교사가 지식을 공연처럼 보여 주는 곳이다.","운동 뒤에 수업하면 집중이 잘된다.","조용한 교실은 학습을 방해한다."], a:0, exp:"바로 앞 문장 'until a student tries an answer' 가 설명. gym = 학생이 직접 연습하는 곳, theater = 교사가 보여 주고 학생은 구경하는 곳(②는 반대).", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Early photographers believed a good picture showed everything clearly. Then a few artists began blurring the background on purpose. Critics called it a mistake, but viewers found that the soft edges pulled their eyes to the single face in focus. Today a blurred background is a standard tool. What looked like a loss of information was in fact ______: by hiding the unimportant, the photo said more.", q:"윗글의 빈칸에 들어갈 말로 가장 적절한 것은?", opts:["a sign of poor equipment","a way of guiding attention","a return to older methods","a demand for sharper lenses"], a:1, exp:"빈칸은 결론 문장. 근거는 'pulled their eyes to the single face' 와 콜론 뒤 'by hiding the unimportant, the photo said more' → **시선을 이끄는 방법**. ①④는 비판자 쪽(반대), ③은 지문에 없다.", why3:"1등급 포인트 — 빈칸 뒤 콜론(:)은 재진술 신호. 콜론 뒤 문장을 바꿔 말한 보기가 정답이고, 지문 단어(mistake, clearly)로 만든 반대 방향 보기는 소거.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"빈칸에 들어갈 말을 영어(4~7단어)로 쓰고, 근거 문장을 지문에서 찾아 빈칸과의 관계(재진술·비유)를 설명하시오.\n\nA full sponge cannot take in more water. A mind works the same way. Students who review new words right after a lecture remember little. Those who rest for ten minutes first remember far more. In other words, learning needs ______.", model:"빈칸: a pause before taking in more (= some empty space before new input)\n근거: 'Those who rest for ten minutes first remember far more.' — 휴식 후 학습이 효과적이라는 실험 결과이며, 첫 문장의 '가득 찬 스펀지는 물을 못 빨아들인다'는 비유를 In other words 로 재진술한 것이 빈칸이다.", rubric:[["빈칸: 휴식·비움의 의미 포함",4],["4~7단어의 영어 구",1],["근거 문장 지목(rest ten minutes / sponge)",3],["재진술·비유 관계 설명",2]], exp:"'more practice' 처럼 지문 방향(쉼)과 반대인 답은 0점. In other words 가 앞 전체를 요약한다는 점을 쓰면 만점.", err:"추론" }
 ],

 "eng-h2-infer-grammar": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"어법상 **틀린** 것은?\n\nA number of volunteers ①has joined the cleanup, and the beach, ②which was covered with plastic, now ③looks ④much cleaner.", opts:["①","②","③","④"], a:0, exp:"**A number of** + 복수 명사는 '많은 ~'으로 복수 취급 → **have** joined. The number of 였다면 단수. ② 계속적 용법 which, ③ 주어 the beach 단수, ④ 비교급 강조 much 는 바르다.", err:"개념" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"문맥상 낱말의 쓰임이 적절하지 **않은** 것은?\n\nHeavy rain ①flooded the valley, so farmers ②lost most of their crops. Luckily, the government ③refused quick help, and the village ④recovered within a year.", opts:["①","②","③","④"], a:2, exp:"Luckily(다행히) + 마을이 회복됨 → 정부는 도움을 **offered(제공)** 했어야 논리가 맞다. refused 는 반대 방향. ①②는 피해, ④는 회복으로 흐름과 맞다.", err:"어휘" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Last spring, our science club noticed that the fish in the school pond **(A) were dying** one by one. Most of them believed **(B) that** the cold weather was the cause. Jiho, **(C) whose** notebook recorded the water temperature every morning, found that the oxygen level dropped after rain washed the road. His records convinced the school to build a filter and **(D) checking** the water weekly.", q:"윗글의 밑줄 친 (A)~(D) 중 어법상 **틀린** 것은?", opts:["(A)","(B)","(C)","(D)"], a:3, exp:"convinced the school **to build** ~ and **to check** — and 앞의 to부정사와 병렬이어야 한다. (A) the fish(복수, one by one) → were, (B) believe + 완전한 절 → that, (C) 소유격 whose + notebook 은 바르다.", why3:"1등급 포인트 — and 뒤 -ing 는 '무엇과 병렬인가'를 and 앞에서 찾는다. fish 는 단·복수 동형이므로 one by one 같은 문맥 단서로 수를 정한다.", err:"실수" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 문장에서 어법상 틀린 부분 하나와 문맥상 어색한 낱말 하나를 찾아 고치고, 각각 이유를 쓰시오.\n\nThe number of tourists visiting the island have doubled since the bridge opened, and local shops report that the crowds have decreased their sales to record highs.", model:"① have → has: 주어의 핵심은 The number(단수)이고 of tourists visiting the island 는 수식어이다.\n② decreased → increased(boosted): 'to record highs(사상 최고치로)' 와 모순되므로 매출은 '늘었다'가 되어야 논리가 맞는다.", rubric:[["has 로 고침",2],["The number 단수 주어 이유",3],["increased/boosted 로 고침",2],["record highs 와의 모순 설명",3]], exp:"doubled 나 report 를 고치면 오답. 어법은 S-V 찾기, 어휘는 앞뒤 논리(record highs)로 판단한다는 점이 드러나야 만점.", err:"개념" }
 ],

 /* ======================= 고2 영어Ⅰ·Ⅱ · 간접 쓰기 ======================= */
 "eng-h2-write-order": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"전체 흐름과 관계 **없는** 문장은?\n\nHouseplants do more than decorate a room. ① They release moisture, which eases dry winter air. ② Caring for them also gives people a daily routine. ③ Garden centers earn most of their profit in spring. ④ Even a single pot on a desk has been linked to lower stress.", opts:["①","②","③","④"], a:2, exp:"주제: 실내 식물이 주는 이점. ③은 식물이라는 소재만 같고 '원예점 매출'로 논점이 다르다. ①②④는 모두 이점(습도·습관·스트레스)을 말한다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"주어진 문장이 들어가기에 가장 적절한 곳은?\n\n[문장] That is why the team added a second, thicker coat of paint.\n\nThe bridge was repainted last summer. (①) Within weeks, the color began to fade in the sun. (②) Engineers found that the first coat was too thin. (③) Now the bridge looks bright even in July. (④)", opts:["①","②","③","④"], a:2, exp:"That is why 는 앞의 **원인**(첫 칠이 너무 얇았다)을 받아 결과(두 번째 칠)를 말함 → ③. ④에 넣으면 '지금 밝다' 뒤에 원인-결과가 거꾸로 온다.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"[주어진 글] A mountain village had no doctor, so people walked four hours to the nearest clinic.\n(A) Thanks to her visits, small problems were treated early, and the long walks became rare.\n(B) Then a young nurse began riding her bike up the mountain road twice a week.\n(C) At first, villagers did not trust her because she was so young, but her careful notes on each patient slowly won them over.", q:"주어진 글 다음에 이어질 글의 순서로 가장 적절한 것은?", opts:["(A)-(C)-(B)","(B)-(A)-(C)","(B)-(C)-(A)","(C)-(B)-(A)"], a:2, exp:"**Then** a young nurse(새 인물 등장, a)(B) → **her**/she 로 받으며 At first 불신 → 신뢰(C) → **her visits** 의 결과, long walks 가 드물어짐(A). (C)(A)의 her 는 (B) 없이는 가리킬 대상이 없다.", why3:"1등급 포인트 — 부정관사 a(새 인물)가 있는 단락이 대명사 her 가 있는 단락보다 먼저. At first → slowly → Thanks to 의 시간·결과 사슬로 확인.", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"문장이 들어갈 위치를 고르고, 문장 속 단서(지시어·연결어) 두 가지로 위치를 설명하시오.\n\n[문장] Such a small change, however, had a surprising effect.\n\nOur cafeteria moved the fruit basket to the checkout counter. (①) Nobody expected much from it. (②) In a month, fruit sales had tripled. (③) Students now grab an apple while in line. (④)", model:"위치: ②\n단서 ① Such a small change 는 첫 문장의 '과일 바구니를 옮긴 일'을 가리킨다. 단서 ② however 는 바로 앞 'Nobody expected much' 와 반대되는 '놀라운 효과'를 예고하므로, 그 효과(sales had tripled)가 나오기 직전인 ②에 들어간다.", rubric:[["위치 ②",4],["Such a small change 의 지시 대상 설명",3],["however 의 역접 관계(기대 없음 ↔ 놀라운 효과) 설명",3]], exp:"①에 넣으면 '기대하지 않았다'가 효과 뒤에 와서 however 의 방향이 어긋난다. 단서를 '자연스러워서'로만 쓰면 단서 항목 0점.", err:"추론" }
 ],

 "eng-h2-write-summary": [
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"요약문의 빈칸 (A), (B)에 알맞은 것은?\n\nIn a study, shoppers who were given a cart bought more items than those carrying a basket, even when they planned to buy the same things.\n→ A larger (A) leads shoppers to (B) more.", opts:["(A) container – (B) buy","(A) budget – (B) save","(A) store – (B) walk","(A) list – (B) plan"], a:0, exp:"cart(큰 것) vs basket(작은 것) → (A) container(담는 것), 결과 bought more → (B) buy. budget·store·list 는 지문에 없는 변수다.", err:"추론" },
  { lv:2, kind:"mc", tag:"내신 중간·기말형", q:"밑줄 친 (a)~(d) 중 가리키는 대상이 **Dr. Han** 인 것끼리 바르게 묶은 것은?\n\nDr. Han handed the test results to Mr. Kim. (a) **He** looked worried, so (b) **he** explained that the numbers were normal. Mr. Kim thanked (c) **him** and promised to return in a month. Dr. Han reminded (d) **him** to bring his medicine list.", opts:["(a), (c)","(b), (c)","(a), (d)","(b), (d)"], a:1, exp:"(a) 결과를 받고 걱정한 사람 = Mr. Kim, (b) 설명한 사람 = Dr. Han, (c) Mr. Kim 이 감사한 대상 = Dr. Han, (d) Dr. Han 이 상기시킨 대상 = Mr. Kim.", err:"추론" },
  { lv:3, kind:"mc", tag:"학평·수능형", data:"Researchers gave two groups of office workers the same report. One group read it on a screen, while the other read a printed copy. Afterwards, both groups answered questions about details and the overall argument. Screen readers did just as well on details, but they found it harder to explain the main argument. They suggested that paper helps readers see how the parts of a text fit together.", q:"다음 글의 내용을 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것은?\n\n→ Compared with screen reading, reading on paper did not change recall of (A) but improved understanding of the text's (B).", opts:["(A) details – (B) structure","(A) arguments – (B) length","(A) details – (B) vocabulary","(A) images – (B) structure"], a:0, exp:"'did just as well on details' → (A) details 는 차이 없음, 'how the parts fit together' → (B) structure(구조). ②④는 (A)가 지문에 없고, ③은 (B) vocabulary 가 근거 없음.", why3:"1등급 포인트 — 요약문의 not A but B 구조에서 A 는 '차이 없던 것', B 는 '차이 난 것'. 마지막 문장의 바꿔 쓰기(fit together → structure)가 (B).", err:"추론" },
  { lv:3, kind:"essay", tag:"서술형", q:"다음 글을 'Although ~, ~' 구조의 영어 한 문장(12~18단어)으로 요약하시오. 그리고 요약에서 지문의 표현을 동의어로 바꿔 쓴 짝을 하나 쓰시오.\n\nPeople who listen to music while studying say they feel more relaxed. However, in tests given right after the study session, they recalled fewer facts than those who studied in silence.", model:"요약: Although studying with music feels relaxing, it leads to poorer recall than studying in silence.\n동의어 짝: recalled fewer facts → poorer recall (또는 feel more relaxed → feels relaxing)", rubric:[["Although 절 + 주절 구조",3],["기분(relaxing) vs 결과(poorer recall) 대비 포함",4],["12~18단어",1],["동의어 짝 제시",2]], exp:"Although 절과 주절의 주어가 모두 '음악 들으며 공부하기'로 일치해야 한다. 지문 문장을 그대로 옮기면 동의어 항목 0점.", err:"추론" }
 ]

});
